<?php
require_once(__DIR__.'/../../includes/load.php');require_once(__DIR__.'/../../config/app.php');require_once(__DIR__.'/funciones_checklist.php');
ensure_mantenimiento_ti_schema();require_permiso('mantenimiento_ti','editar');csrf_require();mti_chk_require_schema();
$findingId=(int)($_POST['hallazgo_id']??0);$actionId=(int)($_POST['accion_id']??0);$stage=(string)($_POST['etapa']??'');$description=trim((string)($_POST['descripcion']??''));
if(!in_array($stage,['DETECCION','EJECUCION','VERIFICACION'],true)){$session->msg('d','Etapa no valida.');redirect('hallazgo.php?id='.$findingId,false);}
$finding=$db->fetch_assoc($db->query("SELECT id FROM activos_mantenimiento_hallazgos WHERE id={$findingId} LIMIT 1"));if(!$finding){$session->msg('d','Hallazgo no encontrado.');redirect('hallazgos.php',false);}
if($actionId>0&&!$db->fetch_assoc($db->query("SELECT id FROM activos_mantenimiento_hallazgo_acciones WHERE id={$actionId} AND hallazgo_id={$findingId} LIMIT 1"))){$session->msg('d','La accion no pertenece al hallazgo.');redirect('hallazgo.php?id='.$findingId,false);}
$stored=null;try{$stored=mti_chk_store_upload($_FILES['evidencia']??[],$findingId,$stage);$user=current_user();$userId=(int)($user['id']??0);$actionSql=$actionId?:'NULL';$db->query("INSERT INTO activos_mantenimiento_hallazgo_evidencias (hallazgo_id,accion_id,etapa,tipo,archivo_ruta,archivo_nombre_original,archivo_mime,descripcion,subido_por) VALUES ({$findingId},{$actionSql},".mti_chk_q($stage).','.mti_chk_q($stored['type']).','.mti_chk_q($stored['relative']).','.mti_chk_q($stored['original']).','.mti_chk_q($stored['mime']).','.mti_chk_nullable($description).",{$userId})");mti_chk_hallazgo_history($findingId,'EVIDENCIA',null,null,'Evidencia '.$stage,$userId,$actionId?:null);$session->msg('s','Evidencia guardada.');}catch(Throwable $e){if($stored)@unlink(mti_chk_evidence_root().DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$stored['relative']));$session->msg('d',$e->getMessage());}redirect('hallazgo.php?id='.$findingId,false);
